static LcValue lc_engine_load_texture(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){LcString *path=lc_lib_string_arg(ctx,argc,argv,0);int w=0,h=0,channels=0;stbi_uc *pixels;LcValue texture,decoded;(void)self;if(!path)return lc_nil();pixels=stbi_load(path->data,&w,&h,&channels,4);if(!pixels){LcValue out[2];out[0]=lc_nil();out[1]=lc_string(ctx,stbi_failure_reason());return lc_tuple_new(ctx,2,out,1);}texture=lc_table(ctx);lc_set_field(ctx,texture,"path",lc_string(ctx,path->data));lc_set_field(ctx,texture,"width",lc_integer(w));lc_set_field(ctx,texture,"height",lc_integer(h));lc_set_field(ctx,texture,"channels",lc_integer(4));decoded=lc_string_n(ctx,(const char *)pixels,(size_t)w*h*4);lc_set_field(ctx,texture,"pixels",decoded);stbi_image_free(pixels);return texture;}
static LcValue lc_engine_sprite(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){LcValue texture;(void)self;if(argc<2||lc_first_value(argv[0]).type!=LC_TABLE){lc_error(ctx,"entity and texture expected");return lc_nil();}texture=lc_first_value(argv[1]);if(texture.type!=LC_TABLE){lc_error(ctx,"load_texture result expected");return lc_nil();}lc_set_field(ctx,argv[0],"texture",lc_retain(texture));if(argc<3)lc_set_field(ctx,argv[0],"width",lc_engine_get(ctx,texture,"width"));if(argc<4)lc_set_field(ctx,argv[0],"height",lc_engine_get(ctx,texture,"height"));if(argc>2)lc_engine_set_number(ctx,argv[0],"width",lc_lib_number_arg(ctx,argc,argv,2,32));if(argc>3)lc_engine_set_number(ctx,argv[0],"height",lc_lib_number_arg(ctx,argc,argv,3,32));return lc_retain(argv[0]);}
static LcValue lc_engine_body(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){static const char *numbers[]={"gravity_scale","gravity_x","gravity_y","restitution","friction","damping",NULL};static const char *booleans[]={"kinematic","solid","grounded",NULL};int i;(void)self;if(argc<2||lc_first_value(argv[0]).type!=LC_TABLE||lc_first_value(argv[1]).type!=LC_TABLE){lc_error(ctx,"entity and body options expected");return lc_nil();}lc_set_field(ctx,argv[0],"solid",lc_bool(1));for(i=0;numbers[i];++i){LcValue v=lc_engine_get(ctx,argv[1],numbers[i]);if(v.type==LC_NUMBER||v.type==LC_INTEGER)lc_set_field(ctx,argv[0],numbers[i],lc_retain(v));lc_release(ctx,v);}for(i=0;booleans[i];++i){LcValue v=lc_engine_get(ctx,argv[1],booleans[i]);if(v.type==LC_BOOL)lc_set_field(ctx,argv[0],booleans[i],lc_retain(v));lc_release(ctx,v);}return lc_retain(argv[0]);}
static LcValue lc_engine_gravity(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){(void)self;if(argc<1||!lc_engine_world(ctx,argv[0]))return lc_nil();lc_engine_set_number(ctx,argv[0],"gravity_x",lc_lib_number_arg(ctx,argc,argv,1,0));lc_engine_set_number(ctx,argv[0],"gravity_y",lc_lib_number_arg(ctx,argc,argv,2,0));return lc_bool(1);}
static LcValue lc_engine_input_state(LcContext *ctx,LcValue world){return lc_engine_get(ctx,world,"input");}
static LcValue lc_engine_input(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){const char *name=lc_lib_name(self);LcValue input,key,value;(void)self;if(argc<1||!lc_engine_world(ctx,argv[0]))return lc_nil();input=lc_engine_input_state(ctx,argv[0]);if(input.type!=LC_TABLE){lc_release(ctx,input);input=lc_table(ctx);lc_set_field(ctx,argv[0],"input",lc_retain(input));}if(!strcmp(name,"clear_input")){lc_set_field(ctx,argv[0],"input",lc_table(ctx));lc_release(ctx,input);return lc_bool(1);}key=argc>1?lc_first_value(argv[1]):lc_nil();if(!strcmp(name,"inject_mouse")){LcValue mouse=lc_table(ctx);lc_engine_set_number(ctx,mouse,"x",lc_lib_number_arg(ctx,argc,argv,1,0));lc_engine_set_number(ctx,mouse,"y",lc_lib_number_arg(ctx,argc,argv,2,0));lc_set_field(ctx,input,"mouse",lc_retain(mouse));lc_release(ctx,mouse);if(argc>4){LcValue buttons=lc_engine_get(ctx,input,"buttons"),clicked=lc_engine_get(ctx,input,"clicked");int down=lc_truthy(lc_first_value(argv[4]));if(buttons.type!=LC_TABLE){lc_release(ctx,buttons);buttons=lc_table(ctx);}if(clicked.type!=LC_TABLE){lc_release(ctx,clicked);clicked=lc_table(ctx);}lc_table_set(ctx,buttons,lc_first_value(argv[3]),lc_bool(down));if(down)lc_table_set(ctx,clicked,lc_first_value(argv[3]),lc_bool(1));lc_set_field(ctx,input,"buttons",lc_retain(buttons));lc_set_field(ctx,input,"clicked",lc_retain(clicked));lc_release(ctx,buttons);lc_release(ctx,clicked);}lc_release(ctx,input);return lc_bool(1);}if(!strcmp(name,"mouse_pos")){LcValue mouse=lc_engine_get(ctx,input,"mouse");double x=mouse.type==LC_TABLE?lc_engine_number(ctx,mouse,"x",0):0,y=mouse.type==LC_TABLE?lc_engine_number(ctx,mouse,"y",0):0;lc_release(ctx,mouse);lc_release(ctx,input);return lc_vec_pair(ctx,x,y);}if(!strcmp(name,"inject_touch")){LcValue touches=lc_engine_get(ctx,input,"touches");int down=lc_truthy(lc_first_value(argv[4]));if(touches.type!=LC_TABLE){lc_release(ctx,touches);touches=lc_table(ctx);}if(down){LcValue point=lc_table(ctx);lc_engine_set_number(ctx,point,"x",lc_lib_number_arg(ctx,argc,argv,2,0));lc_engine_set_number(ctx,point,"y",lc_lib_number_arg(ctx,argc,argv,3,0));lc_table_set(ctx,touches,key,point);lc_release(ctx,point);}else lc_table_set(ctx,touches,key,lc_nil());lc_set_field(ctx,input,"touches",lc_retain(touches));lc_release(ctx,touches);lc_release(ctx,input);return lc_bool(1);}if(!strcmp(name,"inject_key")){const char *field="keys";LcValue values=lc_engine_get(ctx,input,field);int down=lc_truthy(lc_first_value(argv[2]));if(values.type!=LC_TABLE){lc_release(ctx,values);values=lc_table(ctx);}lc_table_set(ctx,values,key,lc_bool(down));lc_set_field(ctx,input,field,lc_retain(values));if(down&&key.type==LC_STRING){LcValue pressed=lc_engine_get(ctx,input,"pressed");if(pressed.type!=LC_TABLE){lc_release(ctx,pressed);pressed=lc_table(ctx);}lc_table_set(ctx,pressed,key,lc_bool(1));lc_set_field(ctx,input,"pressed",lc_retain(pressed));lc_release(ctx,pressed);}lc_release(ctx,values);lc_release(ctx,input);return lc_bool(1);}if(!strcmp(name,"touch_pos")){LcValue touches=lc_engine_get(ctx,input,"touches");value=touches.type==LC_TABLE?lc_table_raw_get(ctx,touches,key):lc_nil();lc_release(ctx,touches);lc_release(ctx,input);if(value.type==LC_TABLE){double x=lc_engine_number(ctx,value,"x",0),y=lc_engine_number(ctx,value,"y",0);lc_release(ctx,value);return lc_vec_pair(ctx,x,y);}lc_release(ctx,value);return lc_nil();}{const char *field=!strcmp(name,"is_key_pressed")?"pressed":!strcmp(name,"is_mouse_clicked")?"clicked":!strcmp(name,"is_mouse_down")?"buttons":"keys";LcValue values=lc_engine_get(ctx,input,field);value=values.type==LC_TABLE?lc_table_raw_get(ctx,values,key):lc_nil();lc_release(ctx,values);lc_release(ctx,input);return lc_bool(lc_truthy(value));}}
static LcValue lc_engine_text(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){LcValue list,item;LcString *text;int index;(void)self;if(argc<2||!lc_engine_world(ctx,argv[0]))return lc_nil();text=lc_lib_string_arg(ctx,argc,argv,1);if(!text)return lc_nil();list=lc_engine_get(ctx,argv[0],"overlay_text");if(list.type!=LC_TABLE){lc_release(ctx,list);list=lc_table(ctx);}item=lc_table(ctx);lc_set_field(ctx,item,"text",lc_string_n(ctx,text->data,text->length));lc_engine_set_number(ctx,item,"x",lc_lib_number_arg(ctx,argc,argv,2,0));lc_engine_set_number(ctx,item,"y",lc_lib_number_arg(ctx,argc,argv,3,0));lc_engine_set_number(ctx,item,"size",lc_lib_number_arg(ctx,argc,argv,4,16));index=lc_table_length(list)+1;lc_table_add(ctx,list,index,item);lc_set_field(ctx,argv[0],"overlay_text",lc_retain(list));lc_release(ctx,list);lc_release(ctx,item);return lc_integer(index);}
static LcValue lc_engine_clear_text(LcContext *ctx,LcFunction *self,int argc,LcValue *argv){(void)self;if(argc<1||!lc_engine_world(ctx,argv[0]))return lc_nil();lc_set_field(ctx,argv[0],"overlay_text",lc_table(ctx));return lc_bool(1);}
#endif
